package com.notificationservice.infrastructure.persistence.adapter;import com.notificationservice.application.port.out.ProcessedEventStore;import com.notificationservice.infrastructure.persistence.entity.ProcessedEventEntity;import com.notificationservice.infrastructure.persistence.repository.JpaProcessedEventRepository;import org.springframework.stereotype.Repository;import java.time.Instant;import java.util.UUID;@Repository public class ProcessedEventAdapter implements ProcessedEventStore{private final JpaProcessedEventRepository r;public ProcessedEventAdapter(JpaProcessedEventRepository r){this.r=r;}public boolean exists(UUID id){return r.existsById(id);}public void record(UUID id,String t,Instant a){r.save(new ProcessedEventEntity(id,t,a));}}
